// spec: specs/html-rtl-dir.md (1.3) · кейс: .qa/tests/html-rtl-dir/RTL-DIR-03.md
// seed: tests/seed.spec.ts (гость) · прод, только чтение: не-GET обрываются, SW выключен.
// Источник: #9c4736 «מה רצוי» «כיוון הדף כולו יהיה RTL» — атрибут не теряется при клиентских переходах.
import { test, expect } from '@playwright/test';
import { prepareReadOnly, dismissPopups, waitReady, expectRtlDocument, LOAD } from './rtl-dir.helpers';

test.use({ serviceWorkers: 'block' });

declare global {
  interface Window { __qaRtlMarker?: number }
}

test.describe('html dir=rtl — SPA-навигация', () => {
  test('главная → поиск → объявление → калькулятор → назад: dir=rtl сохраняется без перезагрузки #9c4736 @desktop @prod-safe', async ({ page, context }) => {
    await prepareReadOnly(context);
    await dismissPopups(page);
    await page.goto('/');
    await waitReady(page, 'home');
    await expectRtlDocument(page, '/');
    await page.evaluate(() => { window.__qaRtlMarker = 1; });

    await page.getByRole('link', { name: 'צפה בכל העסקים' }).first().click();
    await page.waitForURL(/\/search(\?|$)/, LOAD);
    await waitReady(page, 'search');
    await expectRtlDocument(page, '→ /search');

    await page.getByRole('main').locator('a[href^="/businessdetail?id="]').first().click();
    await page.waitForURL(/\/businessdetail\?id=/, LOAD);
    await waitReady(page, 'listing');
    await expectRtlDocument(page, '→ /businessdetail');

    await page.getByRole('banner').getByRole('link', { name: 'מחשבון רכישת עסק', exact: true }).click();
    await page.waitForURL(/\/calculator$/, LOAD);
    await waitReady(page, 'calculator');
    await expectRtlDocument(page, '→ /calculator');

    await page.goBack();
    await page.waitForURL(/\/businessdetail\?id=/, LOAD);
    await waitReady(page, 'listing');
    await expectRtlDocument(page, '← назад на /businessdetail');

    expect(await page.evaluate(() => window.__qaRtlMarker), 'переходы клиентские — метка window сохранилась').toBe(1);
  });
});
